var host = baseUrl.match(/(https?:\/\/.*?)(\/|$)/)[1];
var doc = org.jsoup.Jsoup.parse(result);
var list = doc.select(".chapterlist li a").toArray().map(i => {
    return {
        id: host + i.attr("href"),
        name: i.text(),
    }
});

if (result.indexOf(">查看全部")>-1) {
    let c_id = baseUrl.match(/com\/(.*?)\/$/)[1];
    let url = host + "/chapterlist/"+c_id+"/";
    let json = JSON.parse(String(java.fetch(url, {
        "headers": {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36 Edg/115.0.0.0",
            "Referer": baseUrl,
        }
    }).body().string()));
    // let json = JSON.parse(String(java.getString(url, JSON.stringify({}))))
    let list2 = json.data.list.map(i => {
        i.id = host + "/" + c_id + "/" + i.id + ".html";
        return i;
    })
    list = list.concat(list2)
}
list.reverse();
